/**
 * Candidate marks for Cord's logo, for the `/logo-lab` page to show side by
 * side. Nothing here is chosen; the page exists so the ideas can be judged
 * at several sizes and in the Fuz brand colors before one becomes
 * `static/logo.svg`.
 *
 * Each idea is drawn in fuz_ui's `SvgData` conventions (a `0 0 100 100`
 * view box, one color, paths only), split into filled shapes and stroked
 * lines so one color can tint both. The coils are trochoids and the ring
 * and knot are parametric curves, computed once and pasted in as beziers;
 * edit the numbers by regenerating, not by hand.
 *
 * @module
 */

import { logo_fuz } from '@fuzdev/fuz_ui/logos.ts';
import type { SvgData } from '@fuzdev/fuz_ui/svg.ts';

/** One path of a `LogoIdea`: a filled shape, or a line stroked at `width`. */
export interface LogoIdeaPath {
	kind: 'fill' | 'stroke';
	d: string;
	/** Stroke width in view box units; `stroke` paths only. */
	width?: number;
	/** Stroke line cap, `round` when omitted. */
	cap?: 'round' | 'butt';
	/** Fill rule, for shapes with holes cut out of them. */
	rule?: 'evenodd';
	transform?: string;
}

export interface LogoIdea {
	/** `plug` for the forms a plug can take, `other` for every other direction. */
	group: 'plug' | 'other';
	name: string;
	/** The accessible name the mark would carry, as fuz_ui's logos word theirs. */
	label: string;
	/** What the idea says and where it falls short. */
	note: string;
	paths: Array<LogoIdeaPath>;
}

/**
 * The Fuz logo colors, frozen brand values copied from fuz_ui's `logos.ts`,
 * with the project that wears each one today.
 */
export const LOGO_COLORS: ReadonlyArray<{ name: string; value: string; worn_by: string }> = [
	{ name: 'brown', value: '#84522a', worn_by: 'fuz, fuz_schema' },
	{ name: 'orange', value: '#f4672f', worn_by: 'fuz_template, tsv, zap' },
	{ name: 'yellow', value: '#d8bc31', worn_by: 'fuz_blog' },
	{ name: 'green', value: '#3db33d', worn_by: 'fuz_css' },
	{ name: 'teal', value: '#2e9e6f', worn_by: 'fuz_app' },
	{ name: 'cyan', value: '#1ec3d2', worn_by: 'docs.fuz.dev, svelte-docinfo' },
	{ name: 'blue', value: '#6199d1', worn_by: 'fuz_repos' },
	{ name: 'purple', value: '#8866cc', worn_by: 'mdz' },
	{ name: 'pink', value: '#e55d95', worn_by: 'fuz_code' },
	{ name: 'red', value: '#d93636', worn_by: 'fuz_ui' }
];

/** Renders an idea in one color as the `SvgData` that `Svg` takes. */
export const to_logo_svg_data = (idea: LogoIdea, color: string): SvgData => ({
	label: idea.label,
	paths: idea.paths.map((path) =>
		path.kind === 'fill'
			? { d: path.d, fill: color, 'fill-rule': path.rule, transform: path.transform }
			: {
					d: path.d,
					fill: 'none',
					stroke: color,
					'stroke-width': path.width,
					'stroke-linecap': path.cap ?? 'round',
					'stroke-linejoin': 'round',
					transform: path.transform
				}
	)
});

